/* eslint-disable max-len, max-statements, max-lines, max-lines-per-function */

'use strict';

// MODULES //

var sincos = require( '@stdlib/math/base/special/sincos' );
var TWO_PI = require( '@stdlib/constants/float64/two-pi' );
var floor = require( '@stdlib/math/base/special/floor' );


// FUNCTIONS //

/**
* Resolves an index into the `ch` array (output/workspace array for FFT data).
*
* ## Notes
*
* The `ch` array is used as a workspace for storing intermediate FFT results. It is organized as a three-dimensional logical view with dimensions `[M, L, R]` where:
*
* -   `M` is the sub-sequence length (ido)
* -   `L` is the number of sub-sequences (l1)
* -   `R` is the radix (ip)
*
* The linearized index is computed as: `i + ((k + j*L) * M)`
*
* @private
* @param {NonNegativeInteger} i - index within a sub-sequence (0 to M-1)
* @param {NonNegativeInteger} k - sub-sequence index (0 to L-1)
* @param {NonNegativeInteger} j - radix component index (0 to R-1)
* @param {NonNegativeInteger} L - number of sub-sequences
* @param {NonNegativeInteger} M - sub-sequence length
* @param {integer} stride - stride length
* @param {NonNegativeInteger} offset - index offset
* @returns {NonNegativeInteger} computed index
*/
function chPtr( i, k, j, L, M, stride, offset ) { // ch_ref
	var n = i + ( ( k + (j*L) ) * M );
	return ( n*stride ) + offset;
}

/**
* Resolves an index into the `cc` array (input/output array for FFT data).
*
* ## Notes
*
* The `cc` array stores the input data and final output. It is organized as a three-dimensional logical view with dimensions `[M, R, L]` where:
*
* -   `M` is the sub-sequence length (ido)
* -   `R` is the radix (ip)
* -   `L` is the number of sub-sequences (l1)
*
* Note the dimension order is swapped compared to `ch` for transpose-free multi-stage processing.
*
* The linearized index is computed as: `i + ((j + k*R) * M)`
*
* @private
* @param {NonNegativeInteger} i - index within a sub-sequence (0 to M-1)
* @param {NonNegativeInteger} j - radix component index (0 to R-1)
* @param {NonNegativeInteger} k - sub-sequence index (0 to L-1)
* @param {NonNegativeInteger} R - radix
* @param {NonNegativeInteger} M - sub-sequence length
* @param {integer} stride - stride length
* @param {NonNegativeInteger} offset - index offset
* @returns {NonNegativeInteger} computed index
*/
function ccPtr( i, j, k, R, M, stride, offset ) { // cc_ref
	var n = i + ( ( j + (k*R) ) * M );
	return ( n*stride ) + offset;
}

/**
* Resolves an index into the `c1` array (workspace array with same layout as `ch`).
*
* ## Notes
*
* The `c1` array has the same three-dimensional logical view as `ch`: `[M, L, R]`.
*
* The linearized index is computed as: `i + ((k + j*L) * M)`
*
* @private
* @param {NonNegativeInteger} i - index within a sub-sequence (0 to M-1)
* @param {NonNegativeInteger} k - sub-sequence index (0 to L-1)
* @param {NonNegativeInteger} j - radix component index (0 to R-1)
* @param {NonNegativeInteger} L - number of sub-sequences
* @param {NonNegativeInteger} M - sub-sequence length
* @param {integer} stride - stride length
* @param {NonNegativeInteger} offset - index offset
* @returns {NonNegativeInteger} computed index
*/
function c1Ptr( i, k, j, L, M, stride, offset ) { // c1_ref
	var n = i + ( ( k + (j*L) ) * M );
	return ( n*stride ) + offset;
}

/**
* Resolves an index into the `c2` array (flattened 2D workspace).
*
* ## Notes
*
* The `c2` array is a two-dimensional logical view with dimensions `[idl1, R]` where:
*
* -   `idl1 = M * L` (flattened sub-sequence dimension)
* -   `R` is the radix (ip)
*
* The linearized index is computed as: `ik + (j * idl1)`
*
* @private
* @param {NonNegativeInteger} ik - flattened index (0 to idl1-1)
* @param {NonNegativeInteger} j - radix component index (0 to R-1)
* @param {NonNegativeInteger} idl1 - M * L
* @param {integer} stride - stride length
* @param {NonNegativeInteger} offset - index offset
* @returns {NonNegativeInteger} computed index
*/
function c2Ptr( ik, j, idl1, stride, offset ) { // c2_ref
	var n = ik + ( j * idl1 );
	return ( n*stride ) + offset;
}

/**
* Resolves an index into the `ch2` array (flattened 2D workspace, same layout as `c2`).
*
* ## Notes
*
* The `ch2` array has the same two-dimensional logical view as `c2`: `[idl1, R]`.
*
* The linearized index is computed as: `ik + (j * idl1)`
*
* @private
* @param {NonNegativeInteger} ik - flattened index (0 to idl1-1)
* @param {NonNegativeInteger} j - radix component index (0 to R-1)
* @param {NonNegativeInteger} idl1 - M * L
* @param {integer} stride - stride length
* @param {NonNegativeInteger} offset - index offset
* @returns {NonNegativeInteger} computed index
*/
function ch2Ptr( ik, j, idl1, stride, offset ) { // ch2_ref
	var n = ik + ( j * idl1 );
	return ( n*stride ) + offset;
}


// MAIN //

/**
* Performs one general radix stage within a forward Fourier transform for a real-valued sequence.
*
* @private
* @param {NonNegativeInteger} M - number of elements in each sub-sequence to be transformed (ido)
* @param {NonNegativeInteger} R - radix of the transform (ip)
* @param {NonNegativeInteger} L - number of sub-sequences to be transformed (l1)
* @param {NonNegativeInteger} ML - M * L (idl1)
* @param {Float64Array} cc - input/output array containing sequences to be transformed
* @param {integer} scc - stride length for `cc`
* @param {NonNegativeInteger} occ - index offset for `cc`
* @param {Float64Array} c1 - first work array (aliased view of cc)
* @param {integer} sc1 - stride length for `c1`
* @param {NonNegativeInteger} oc1 - index offset for `c1`
* @param {Float64Array} c2 - second work array (aliased view of cc, 2D layout)
* @param {integer} sc2 - stride length for `c2`
* @param {NonNegativeInteger} oc2 - index offset for `c2`
* @param {Float64Array} ch - output/workspace array containing transformed sequences
* @param {integer} sch - stride length for `ch`
* @param {NonNegativeInteger} och - index offset for `ch`
* @param {Float64Array} ch2 - work array for transformed sequences (aliased view of ch, 2D layout)
* @param {integer} sch2 - stride length for `ch2`
* @param {NonNegativeInteger} och2 - index offset for `ch2`
* @param {Float64Array} twiddles - array of twiddle factors
* @param {integer} stw - stride length for `twiddles`
* @param {NonNegativeInteger} otw - index offset for `twiddles`
* @returns {void}
*/
function radfg( M, R, L, ML, cc, scc, occ, c1, sc1, oc1, c2, sc2, oc2, ch, sch, och, ch2, sch2, och2, twiddles, stw, otw ) { // eslint-disable-line max-params
	var ar1h;
	var ar2h;
	var idij;
	var ic2o;
	var ic1o;
	var ich;
	var icc;
	var Rph;
	var Rp1;
	var ih1;
	var ih2;
	var ih3;
	var ih4;
	var ic1;
	var ic2;
	var ic3;
	var ic4;
	var it1;
	var it2;
	var io1;
	var io2;
	var io3;
	var io4;
	var dc2;
	var ai1;
	var ai2;
	var ar1;
	var ar2;
	var ds2;
	var nbd;
	var dcp;
	var arg;
	var dsp;
	var sc;
	var im;
	var ik;
	var is;
	var jc;
	var lc;
	var j2;
	var i;
	var j;
	var k;
	var l;

	arg = TWO_PI / R;
	sc = sincos( arg );
	dcp = sc[ 1 ]; // cos(2π/R)
	dsp = sc[ 0 ]; // sin(2π/R)
	Rph = floor( ( R + 1 ) / 2 );
	Rp1 = R + 1;
	nbd = floor( ( M - 1 ) / 2 );

	/*
	* Initialize workspace and apply twiddle factors.
	*
	* When M = 1, we simply copy from ch2 to c2 (DC component only). Otherwise, we need to apply twiddle factors to each radix component.
	*/
	if ( M === 1 ) {
		// Copy ch2 to c2 (DC component only)...
		for ( ik = 0; ik < ML; ik++ ) {
			ic2o = c2Ptr( ik, 0, ML, sc2, oc2 );
			ich = ch2Ptr( ik, 0, ML, sch2, och2 );
			c2[ ic2o ] = ch2[ ich ];
		}
	} else {
		// Copy first column of c2 to ch2...
		for ( ik = 0; ik < ML; ik++ ) {
			ich = ch2Ptr( ik, 0, ML, sch2, och2 );
			ic2o = c2Ptr( ik, 0, ML, sc2, oc2 );
			ch2[ ich ] = c2[ ic2o ];
		}

		// Copy DC component from c1 to ch for each radix component...
		for ( j = 1; j < R; j++ ) {
			for ( k = 0; k < L; k++ ) {
				ih1 = chPtr( 0, k, j, L, M, sch, och );
				ic1 = c1Ptr( 0, k, j, L, M, sc1, oc1 );
				ch[ ih1 ] = c1[ ic1 ];
			}
		}

		// Apply twiddle factors to each radix component...
		if ( nbd <= L ) {
			// Loop order optimized for small nbd
			is = 0;
			for ( j = 1; j < R; j++ ) {
				idij = is;
				for ( i = 2; i < M; i += 2 ) {
					for ( k = 0; k < L; k++ ) {
						// Resolve indices
						ih1 = chPtr( i-1, k, j, L, M, sch, och );
						ih2 = chPtr( i, k, j, L, M, sch, och );
						ic1 = c1Ptr( i-1, k, j, L, M, sc1, oc1 );
						ic2 = c1Ptr( i, k, j, L, M, sc1, oc1 );
						it1 = ( idij * stw ) + otw;
						it2 = ( (idij+1) * stw ) + otw;

						// Twiddle multiplication: ch = W * c1
						ch[ ih1 ] = ( twiddles[ it1 ] * c1[ ic1 ] ) + ( twiddles[ it2 ] * c1[ ic2 ] );
						ch[ ih2 ] = ( twiddles[ it1 ] * c1[ ic2 ] ) - ( twiddles[ it2 ] * c1[ ic1 ] );
					}
					idij += 2;
				}
				is += M;
			}
		} else {
			// Loop order optimized for large nbd
			is = 0;
			for ( j = 1; j < R; j++ ) {
				for ( k = 0; k < L; k++ ) {
					idij = is;
					for ( i = 2; i < M; i += 2 ) {
						// Resolve indices
						ih1 = chPtr( i-1, k, j, L, M, sch, och );
						ih2 = chPtr( i, k, j, L, M, sch, och );
						ic1 = c1Ptr( i-1, k, j, L, M, sc1, oc1 );
						ic2 = c1Ptr( i, k, j, L, M, sc1, oc1 );
						it1 = ( idij * stw ) + otw;
						it2 = ( (idij+1) * stw ) + otw;

						// Twiddle multiplication: ch = W * c1
						ch[ ih1 ] = ( twiddles[ it1 ] * c1[ ic1 ] ) + ( twiddles[ it2 ] * c1[ ic2 ] );
						ch[ ih2 ] = ( twiddles[ it1 ] * c1[ ic2 ] ) - ( twiddles[ it2 ] * c1[ ic1 ] );

						idij += 2;
					}
				}
				is += M;
			}
		}

		/*
		* Combine conjugate-symmetric pairs.
		*
		* For each pair of harmonics (j, jc) where jc = R+1-j, form symmetric and antisymmetric combinations.
		*/
		if ( nbd >= L ) {
			for ( j = 1; j < Rph; j++ ) {
				jc = Rp1 - j - 1;
				for ( k = 0; k < L; k++ ) {
					for ( i = 2; i < M; i += 2 ) {
						// Resolve ch indices
						ih1 = chPtr( i-1, k, j, L, M, sch, och );
						ih2 = chPtr( i, k, j, L, M, sch, och );
						ih3 = chPtr( i-1, k, jc, L, M, sch, och );
						ih4 = chPtr( i, k, jc, L, M, sch, och );

						// Resolve c1 indices
						ic1 = c1Ptr( i-1, k, j, L, M, sc1, oc1 );
						ic2 = c1Ptr( i, k, j, L, M, sc1, oc1 );
						ic3 = c1Ptr( i-1, k, jc, L, M, sc1, oc1 );
						ic4 = c1Ptr( i, k, jc, L, M, sc1, oc1 );

						// Symmetric/antisymmetric combinations
						c1[ ic1 ] = ch[ ih1 ] + ch[ ih3 ];
						c1[ ic3 ] = ch[ ih2 ] - ch[ ih4 ];
						c1[ ic2 ] = ch[ ih2 ] + ch[ ih4 ];
						c1[ ic4 ] = ch[ ih3 ] - ch[ ih1 ];
					}
				}
			}
		} else {
			for ( j = 1; j < Rph; j++ ) {
				jc = Rp1 - j - 1;
				for ( i = 2; i < M; i += 2 ) {
					for ( k = 0; k < L; k++ ) {
						// Resolve ch indices
						ih1 = chPtr( i-1, k, j, L, M, sch, och );
						ih2 = chPtr( i, k, j, L, M, sch, och );
						ih3 = chPtr( i-1, k, jc, L, M, sch, och );
						ih4 = chPtr( i, k, jc, L, M, sch, och );

						// Resolve c1 indices
						ic1 = c1Ptr( i-1, k, j, L, M, sc1, oc1 );
						ic2 = c1Ptr( i, k, j, L, M, sc1, oc1 );
						ic3 = c1Ptr( i-1, k, jc, L, M, sc1, oc1 );
						ic4 = c1Ptr( i, k, jc, L, M, sc1, oc1 );

						// Symmetric/antisymmetric combinations
						c1[ ic1 ] = ch[ ih1 ] + ch[ ih3 ];
						c1[ ic3 ] = ch[ ih2 ] - ch[ ih4 ];
						c1[ ic2 ] = ch[ ih2 ] + ch[ ih4 ];
						c1[ ic4 ] = ch[ ih3 ] - ch[ ih1 ];
					}
				}
			}
		}
	}

	// Combine DC components for conjugate pairs...
	for ( j = 1; j < Rph; j++ ) {
		jc = Rp1 - j - 1;
		for ( k = 0; k < L; k++ ) {
			ih1 = chPtr( 0, k, j, L, M, sch, och );
			ih2 = chPtr( 0, k, jc, L, M, sch, och );
			ic1 = c1Ptr( 0, k, j, L, M, sc1, oc1 );
			ic2 = c1Ptr( 0, k, jc, L, M, sc1, oc1 );
			c1[ ic1 ] = ch[ ih1 ] + ch[ ih2 ];
			c1[ ic2 ] = ch[ ih2 ] - ch[ ih1 ];
		}
	}

	/*
	* Apply DFT matrix to combine all radix components.
	*
	* This implements the radix-R butterfly using rotation factors:
	*
	*     ar1 + j*ai1 = exp(j * 2π * l / R)
	*/
	ar1 = 1.0;
	ai1 = 0.0;
	for ( l = 1; l < Rph; l++ ) {
		lc = Rp1 - l - 1;
		ar1h = ( dcp * ar1 ) - ( dsp * ai1 );
		ai1 = ( dcp * ai1 ) + ( dsp * ar1 );
		ar1 = ar1h;
		for ( ik = 0; ik < ML; ik++ ) {
			ich = ch2Ptr( ik, l, ML, sch2, och2 );
			ic1o = ch2Ptr( ik, lc, ML, sch2, och2 );
			ic2o = c2Ptr( ik, 0, ML, sc2, oc2 );
			ic1 = c2Ptr( ik, 1, ML, sc2, oc2 );
			ic2 = c2Ptr( ik, R-1, ML, sc2, oc2 );
			ch2[ ich ] = c2[ ic2o ] + ( ar1 * c2[ ic1 ] );
			ch2[ ic1o ] = ai1 * c2[ ic2 ];
		}
		dc2 = ar1;
		ds2 = ai1;
		ar2 = ar1;
		ai2 = ai1;
		for ( j = 2; j < Rph; j++ ) {
			jc = Rp1 - j - 1;
			ar2h = ( dc2 * ar2 ) - ( ds2 * ai2 );
			ai2 = ( dc2 * ai2 ) + ( ds2 * ar2 );
			ar2 = ar2h;
			for ( ik = 0; ik < ML; ik++ ) {
				ich = ch2Ptr( ik, l, ML, sch2, och2 );
				ic1o = ch2Ptr( ik, lc, ML, sch2, och2 );
				ic1 = c2Ptr( ik, j, ML, sc2, oc2 );
				ic2 = c2Ptr( ik, jc, ML, sc2, oc2 );
				ch2[ ich ] += ar2 * c2[ ic1 ];
				ch2[ ic1o ] += ai2 * c2[ ic2 ];
			}
		}
	}

	// Accumulate all radix components into DC term...
	for ( j = 1; j < Rph; j++ ) {
		for ( ik = 0; ik < ML; ik++ ) {
			ich = ch2Ptr( ik, 0, ML, sch2, och2 );
			ic1 = c2Ptr( ik, j, ML, sc2, oc2 );
			ch2[ ich ] += c2[ ic1 ];
		}
	}

	// Copy DC component to output array...
	if ( M >= L ) {
		for ( k = 0; k < L; k++ ) {
			for ( i = 0; i < M; i++ ) {
				icc = ccPtr( i, 0, k, R, M, scc, occ );
				ih1 = chPtr( i, k, 0, L, M, sch, och );
				cc[ icc ] = ch[ ih1 ];
			}
		}
	} else {
		for ( i = 0; i < M; i++ ) {
			for ( k = 0; k < L; k++ ) {
				icc = ccPtr( i, 0, k, R, M, scc, occ );
				ih1 = chPtr( i, k, 0, L, M, sch, och );
				cc[ icc ] = ch[ ih1 ];
			}
		}
	}

	// Store harmonic components in conjugate-symmetric format...
	for ( j = 1; j < Rph; j++ ) {
		jc = Rp1 - j - 1;
		j2 = 2 * j;
		for ( k = 0; k < L; k++ ) {
			io1 = ccPtr( M-1, j2-1, k, R, M, scc, occ );
			io2 = ccPtr( 0, j2, k, R, M, scc, occ );
			ih1 = chPtr( 0, k, j, L, M, sch, och );
			ih2 = chPtr( 0, k, jc, L, M, sch, och );
			cc[ io1 ] = ch[ ih1 ];
			cc[ io2 ] = ch[ ih2 ];
		}
	}

	// When M = 1, there's nothing more to do...
	if ( M === 1 ) {
		return;
	}

	/*
	* Store complex harmonic pairs in folded format.
	*
	* For each harmonic pair, store the real parts and imaginary parts in the appropriate positions to maintain conjugate symmetry in the output array.
	*/
	if ( nbd >= L ) {
		for ( j = 1; j < Rph; j++ ) {
			jc = Rp1 - j - 1;
			j2 = 2 * j;
			for ( k = 0; k < L; k++ ) {
				for ( i = 2; i < M; i += 2 ) {
					im = M - i; // mirror index (0-based)

					// Resolve ch indices
					ih1 = chPtr( i-1, k, j, L, M, sch, och );
					ih2 = chPtr( i, k, j, L, M, sch, och );
					ih3 = chPtr( i-1, k, jc, L, M, sch, och );
					ih4 = chPtr( i, k, jc, L, M, sch, och );

					// Resolve cc output indices
					io1 = ccPtr( i-1, j2, k, R, M, scc, occ );
					io2 = ccPtr( im-1, j2-1, k, R, M, scc, occ );
					io3 = ccPtr( i, j2, k, R, M, scc, occ );
					io4 = ccPtr( im, j2-1, k, R, M, scc, occ );

					// Store folded format
					cc[ io1 ] = ch[ ih1 ] + ch[ ih3 ];
					cc[ io2 ] = ch[ ih1 ] - ch[ ih3 ];
					cc[ io3 ] = ch[ ih2 ] + ch[ ih4 ];
					cc[ io4 ] = ch[ ih4 ] - ch[ ih2 ];
				}
			}
		}
	} else {
		for ( j = 1; j < Rph; j++ ) {
			jc = Rp1 - j - 1;
			j2 = 2 * j;
			for ( i = 2; i < M; i += 2 ) {
				im = M - i; // mirror index (0-based)
				for ( k = 0; k < L; k++ ) {
					// Resolve ch indices
					ih1 = chPtr( i-1, k, j, L, M, sch, och );
					ih2 = chPtr( i, k, j, L, M, sch, och );
					ih3 = chPtr( i-1, k, jc, L, M, sch, och );
					ih4 = chPtr( i, k, jc, L, M, sch, och );

					// Resolve cc output indices
					io1 = ccPtr( i-1, j2, k, R, M, scc, occ );
					io2 = ccPtr( im-1, j2-1, k, R, M, scc, occ );
					io3 = ccPtr( i, j2, k, R, M, scc, occ );
					io4 = ccPtr( im, j2-1, k, R, M, scc, occ );

					// Store folded format
					cc[ io1 ] = ch[ ih1 ] + ch[ ih3 ];
					cc[ io2 ] = ch[ ih1 ] - ch[ ih3 ];
					cc[ io3 ] = ch[ ih2 ] + ch[ ih4 ];
					cc[ io4 ] = ch[ ih4 ] - ch[ ih2 ];
				}
			}
		}
	}
}


// EXPORTS //

module.exports = radfg;
